mapper.select:
SELECT id, type, title, content, business_type, business_id, action_url,
       read_status, read_time, create_time, expire_time
FROM sys_notification

    recipient_id = #{recipientId}
    AND status = 1
    AND (expire_time IS NULL OR expire_time > CURRENT_TIMESTAMP)

        AND type = #{query.type}


        AND read_status = #{query.readStatus}


ORDER BY read_status ASC, create_time DESC, id DESC
